"Customer name: \n\nTelephone: \n\nE-mail address: \n\nPizza Size\n\n Small\n\n Medium\n\n Large\n\nPizza Toppings\n\n Bacon\n\n Extra Cheese\n\n Onion\n\n Mushroom\n\nPreferred delivery time: \n\nDelivery instructions: \n\nSubmit order"
### Ran Playwright code
```js
await (async page => {
          const activePage = page;
          let text = await activePage.evaluate(
            ({ maxLength, method, attributeName }) => {
              const body = document.body;
              if (!body) return '';
              if (method === 'visible') {
                return 'true';
              }
              if (method === 'attribute') {
                if (!attributeName) return '';
                return String(body.getAttribute(attributeName) || '').slice(0, maxLength);
              }
              if (method === 'value') {
                return String(body.getAttribute('value') || '').slice(0, maxLength);
              }
              if (method === 'textContent') {
                return String(body.textContent || '').slice(0, maxLength);
              }
              return String(body.innerText || '').slice(0, maxLength);
            },
            {
              maxLength: 1600,
              method: "innerText",
              attributeName: "",
            }
          );
          if (!text || text.length < 100) {
            for (const frame of activePage.frames()) {
              if (frame === activePage.mainFrame()) continue;
              const frameText = await frame
                .evaluate(
                  ({ maxLength, method, attributeName }) => {
                    const body = document.body;
                    if (!body) return '';
                    if (method === 'visible') {
                      return 'true';
                    }
                    if (method === 'attribute') {
                      if (!attributeName) return '';
                      return String(body.getAttribute(attributeName) || '').slice(0, maxLength);
                    }
                    if (method === 'value') {
                      return String(body.getAttribute('value') || '').slice(0, maxLength);
                    }
                    if (method === 'textContent') {
                      return String(body.textContent || '').slice(0, maxLength);
                    }
                    return String(body.innerText || '').slice(0, maxLength);
                  },
                  {
                    maxLength: 1600,
                    method: "innerText",
                    attributeName: "",
                  }
                )
                .catch(() => '');
              if (frameText && frameText.length > text.length) {
                text = frameText;
              }
            }
          }
          return text;
        })(page);
```

